import Foundation

/// Versioned references only. No file content or failure-detail log is stored.
struct ShelfPinnedRecord: Codable, Equatable {
    let path: String
    let addedAt: Date
    var bookmark: Data?
}

struct ShelfPinnedArchive: Codable {
    let version: Int
    let items: [ShelfPinnedRecord]
}

struct ShelfReferenceExport {
    let data: Data
    let count: Int
    let includesUnsavedChanges: Bool
    let bookmarkCount: Int

    /// Publish only after verifying the generated bytes. No original file is
    /// opened; production passes this app's own Application Support directory.
    func write(to directory: URL) throws -> URL {
        let manager = FileManager.default
        try manager.createDirectory(at: directory, withIntermediateDirectories: true)
        let identifier = UUID().uuidString
        let staging = directory.appendingPathComponent(".pending-\(identifier)")
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "yyyyMMdd-HHmmss"
        let target = directory.appendingPathComponent("搁这儿备份-\(formatter.string(from: Date()))-\(identifier.prefix(8)).json")
        try data.write(to: staging, options: .withoutOverwriting)
        defer { try? manager.removeItem(at: staging) }
        try manager.setAttributes([.posixPermissions: 0o600], ofItemAtPath: staging.path)
        guard try Data(contentsOf: staging) == data else { throw ShelfReferenceExportProblem.writeFailed }
        try manager.moveItem(at: staging, to: target)
        return target
    }
}

enum ShelfReferenceExportProblem: Error, Equatable {
    case noPinnedItems, writeFailed, tooLarge
}

enum ShelfPersistenceProblem: Error, Equatable {
    case unreadable, saveFailed, recoveryNeedsSpace, importConflict

    var message: String {
        switch self {
        case .unreadable: "固定记录无法读取，原记录已保留。请重试读取或恢复备份。"
        case .importConflict: "旧固定记录与现有临时项重叠，请先固定或移除相应临时引用，再导入。"
        case .recoveryNeedsSpace: "恢复固定记录需要空间，请先移除临时引用，再重试读取。"
        case .saveFailed: "固定记录尚未保存。请重试保存，退出前不要依赖这次更改。"
        }
    }
}

/// UserDefaults does not offer an fsync guarantee. Read-back detects immediate
/// write rejection; power-loss durability still needs real signed-runtime testing.
struct ShelfPersistence {
    static let legacyKey = "DockShelf.pinnedItems.v1"
    static let currentKey = "DockShelf.pinnedItems.v2"
    static let backupKey = "DockShelf.pinnedItems.recovery.v2"
    static let legacyBackupKey = "DockShelf.pinnedItems.legacyBackup.v1"

    let defaults: UserDefaults
    private let recoveryDirectory: URL
    var write: (Data, String) throws -> Void

    init(defaults: UserDefaults, recoveryDirectory: URL? = nil, write: ((Data, String) throws -> Void)? = nil) {
        self.defaults = defaults
        self.recoveryDirectory = recoveryDirectory ?? FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("com.claracore.dockshelf/Recovery", isDirectory: true)
        self.write = write ?? { data, key in
            defaults.set(data, forKey: key)
            guard defaults.data(forKey: key) == data else { throw ShelfPersistenceProblem.saveFailed }
        }
    }

    struct Loaded {
        let records: [ShelfPinnedRecord]
        let migrated: Bool
    }

    func load() throws -> Loaded {
        if let raw = defaults.object(forKey: Self.currentKey) {
            guard let data = raw as? Data else { throw ShelfPersistenceProblem.unreadable }
            return Loaded(records: try decode(data), migrated: false)
        }
        guard let raw = defaults.object(forKey: Self.legacyKey) else {
            return Loaded(records: [], migrated: false)
        }
        guard let data = raw as? Data,
              let records = try? JSONDecoder().decode([ShelfPinnedRecord].self, from: data) else {
            throw ShelfPersistenceProblem.unreadable
        }
        try validate(records)
        // Match the v1 loader's chronological ordering, including stable ties.
        let ordered = records.enumerated().sorted {
            $0.element.addedAt == $1.element.addedAt ? $0.offset < $1.offset : $0.element.addedAt < $1.element.addedAt
        }.map(\.element)
        // Exact old bytes survive migration. Never overwrite a prior recovery copy.
        if defaults.object(forKey: Self.legacyBackupKey) == nil {
            try write(data, Self.legacyBackupKey)
        }
        try save(ordered)
        return Loaded(records: ordered, migrated: true)
    }

    func save(_ records: [ShelfPinnedRecord]) throws {
        try validate(records)
        if let raw = defaults.object(forKey: Self.currentKey) {
            guard let previous = raw as? Data else { throw ShelfPersistenceProblem.unreadable }
            _ = try decode(previous) // Do not overwrite corruption with an apparent empty shelf.
            try write(previous, Self.backupKey)
        }
        let data = try JSONEncoder().encode(ShelfPinnedArchive(version: 2, items: records))
        try write(data, Self.currentKey)
    }

    var hasBackup: Bool {
        if let data = defaults.data(forKey: Self.backupKey), (try? decode(data)) != nil { return true }
        if let data = defaults.data(forKey: Self.legacyBackupKey),
           let records = try? JSONDecoder().decode([ShelfPinnedRecord].self, from: data),
           (try? validate(records)) != nil { return true }
        return false
    }

    func restoreBackup() throws {
        let replacement: Data
        if let data = defaults.data(forKey: Self.backupKey), (try? decode(data)) != nil {
            replacement = data
        } else if let data = defaults.data(forKey: Self.legacyBackupKey) {
            let records = try JSONDecoder().decode([ShelfPinnedRecord].self, from: data)
            try validate(records)
            replacement = try JSONEncoder().encode(ShelfPinnedArchive(version: 2, items: records))
        } else {
            throw ShelfPersistenceProblem.unreadable
        }
        // Preserve the exact rejected value before a user-requested restoration.
        if let raw = defaults.object(forKey: Self.currentKey) {
            let copyID = UUID().uuidString
            let key = "DockShelf.pinnedItems.rejected.\(copyID)"
            let encoded = try PropertyListSerialization.data(fromPropertyList: [Self.currentKey: raw], format: .binary, options: 0)
            defaults.set(raw, forKey: key)
            let readback = try PropertyListSerialization.data(fromPropertyList: [Self.currentKey: defaults.object(forKey: key) as Any], format: .binary, options: 0)
            guard encoded == readback else { throw ShelfPersistenceProblem.saveFailed }
            try FileManager.default.createDirectory(at: recoveryDirectory, withIntermediateDirectories: true)
            let file = recoveryDirectory.appendingPathComponent("rejected-\(copyID).plist")
            try encoded.write(to: file, options: .atomic)
            let restored = try Data(contentsOf: file)
            let payload = try PropertyListSerialization.propertyList(from: restored, format: nil) as? [String: Any]
            guard restored == encoded, payload?[Self.currentKey] != nil else { throw ShelfPersistenceProblem.saveFailed }
        }
        try write(replacement, Self.currentKey)
    }

    func decodeImport(_ data: Data) throws -> [ShelfPinnedRecord] {
        guard data.count <= 2_000_000 else { throw ShelfPersistenceProblem.unreadable }
        let records: [ShelfPinnedRecord]
        if let archive = try? JSONDecoder().decode(ShelfPinnedArchive.self, from: data) {
            guard [2, 3].contains(archive.version) else { throw ShelfPersistenceProblem.unreadable }
            records = archive.items
        } else if let legacy = try? JSONDecoder().decode([ShelfPinnedRecord].self, from: data) {
            records = legacy.enumerated().sorted {
                $0.element.addedAt == $1.element.addedAt ? $0.offset < $1.offset : $0.element.addedAt < $1.element.addedAt
            }.map(\.element)
        } else if let plist = try? PropertyListSerialization.propertyList(from: data, format: nil) as? [String: Any],
                  let nested = (plist[Self.currentKey] ?? plist[Self.legacyKey]) as? Data {
            return try decodeImport(nested)
        } else { throw ShelfPersistenceProblem.unreadable }
        try validate(records)
        // A backup retains existing app-scoped bookmarks. The OS decides whether
        // each grant can be resolved; a path or opaque bytes never imply success.
        return records
    }

    func preserveImportedBytes(_ data: Data) throws {
        try write(data, "DockShelf.pinnedItems.imported.\(UUID().uuidString)")
    }

    func encodeExport(_ records: [ShelfPinnedRecord]) throws -> Data {
        try validate(records)
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        let data = try encoder.encode(ShelfPinnedArchive(version: 3, items: records))
        guard data.count <= 2_000_000 else { throw ShelfReferenceExportProblem.tooLarge }
        return data
    }

    private func decode(_ data: Data) throws -> [ShelfPinnedRecord] {
        do {
            let archive = try JSONDecoder().decode(ShelfPinnedArchive.self, from: data)
            guard archive.version == 2 else { throw ShelfPersistenceProblem.unreadable }
            try validate(archive.items)
            return archive.items
        } catch { throw ShelfPersistenceProblem.unreadable }
    }

    private func validate(_ records: [ShelfPinnedRecord]) throws {
        var paths = Set<String>()
        guard records.count <= 20 else { throw ShelfPersistenceProblem.unreadable }
        for record in records {
            guard record.path.hasPrefix("/"),
                  record.path == URL(fileURLWithPath: record.path).standardizedFileURL.path,
                  paths.insert(record.path).inserted else { throw ShelfPersistenceProblem.unreadable }
        }
    }
}
